svg.script:
//
(function () {
  var svg = document.getElementById('fft-sc');
  if (!svg) return;

  var iT = svg.querySelector('#fft-it');
  var iD = svg.querySelector('#fft-id');
  var ann = svg.querySelector('#fft-ann');

  var DESCS = {
    peak:  ['5.83 Hz — Fundamental bending mode',
            'Dominant peak of the ring-down FFT. Beam\'s first bending frequency; matches theory: f = (1.875²/(2πL²))·√(EI/ρA) ≈ 5.81 Hz.'],
    floor: ['Noise floor',
            'Background amplitude ≈ 0.3. Minor bumps near 22 Hz and 35 Hz are ambient room resonances, not beam modes.'],
    marker:['Peak marker at 5.83 Hz',
            'Dashed cursor marks the measured natural frequency. Agrees with the theoretical prediction to within 0.3%.']
  };

  function reset() {
    svg.querySelectorAll('.fft-zone.lit').forEach(function(z){ z.classList.remove('lit'); });
    svg.querySelector('#fft-mk').classList.remove('lit');
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover the spectrum to explore';
  }

  function show(id) {
    var d = DESCS[id];
    if (!d) return;
    if (iT) iT.textContent = d[0];
    if (iD) iD.textContent = d[1];
  }

  svg.querySelectorAll('.fft-zone').forEach(function(z) {
    var id = z.dataset.id;
    z.addEventListener('mouseenter', function(){ reset(); z.classList.add('lit'); show(id); });
    z.addEventListener('click',      function(){ reset(); z.classList.add('lit'); show(id); });
    z.addEventListener('mouseleave', reset);
  });

  var mkHit = svg.querySelector('#fft-mk-hit');
  var mk    = svg.querySelector('#fft-mk');
  if (mkHit && mk) {
    mkHit.addEventListener('mouseenter', function(){
      reset(); mk.classList.add('lit'); show('marker');
    });
    mkHit.addEventListener('click',      function(){
      reset(); mk.classList.add('lit'); show('marker');
    });
    mkHit.addEventListener('mouseleave', reset);
  }

  svg.addEventListener('click', function(e){
    if (!e.target.closest('.fft-zone') && e.target.id !== 'fft-mk-hit') reset();
  });

  // ── Build-up ────────────────────────────────────────────────
  if (window.matchMedia('(prefers-reduced-motion:reduce)').matches) {
    var curve = svg.querySelector('#fft-curve');
    if (curve) curve.classList.add('ready');
    if (mk) mk.classList.add('ready');
    if (ann) ann.style.opacity = 1;
    return;
  }

  // Curve draws on from left to right via stroke-dashoffset at t=600ms
  setTimeout(function () {
    var curve = svg.querySelector('#fft-curve');
    if (!curve) return;
    var len = curve.getTotalLength ? curve.getTotalLength() : 800;
    curve.style.strokeDasharray  = len;
    curve.style.strokeDashoffset = len;
    curve.classList.add('ready');
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){
        curve.style.transition = 'stroke-dashoffset 1.1s cubic-bezier(.4,0,.2,1)';
        curve.style.strokeDashoffset = 0;
      });
    });
  }, 600);

  // Marker and annotation appear after curve reaches peak area (~t=1500ms, ~1/7 through)
  setTimeout(function () {
    if (mk) mk.classList.add('ready');
    if (ann) ann.style.opacity = 1;
  }, 1500);
})();
//
